import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';

const socket = io('http://localhost:3001');

const SimultaneousEvaluation = () => {
    const [questions, setQuestions] = useState({});
    const [participants, setParticipants] = useState([]);
    const [currentSectionIndex, setCurrentSectionIndex] = useState(0);
    const [scores, setScores] = useState({});
    const [juryName, setJuryName] = useState('');

    useEffect(() => {
        const storedQuestions = JSON.parse(sessionStorage.getItem('evaluationQuestions'));
        const juryInfo = JSON.parse(sessionStorage.getItem('juryInfo'));
        if (storedQuestions) setQuestions(storedQuestions);
        if (juryInfo) setJuryName(juryInfo.juryName);

        // Fetch participants
        const mockParticipants = [
            { id: 1, name: 'Candidate 1', team: 'Team A' },
            { id: 2, name: 'Candidate 2', team: 'Team A' },
            { id: 3, name: 'Candidate 3', team: 'Team B' },
        ];
        setParticipants(mockParticipants);
    }, []);

    const sectionNames = Object.keys(questions);
    const currentSectionName = sectionNames[currentSectionIndex];
    const currentCriterions = questions[currentSectionName] || [];

    const handleScoreChange = (participantId, criterionName, value) => {
        const newScores = {
            ...scores,
            [participantId]: {
                ...scores[participantId],
                [criterionName]: value
            }
        };
        setScores(newScores);
    };

    const handleSubmitSection = () => {
        // Submit all scores for the current section
        participants.forEach(p => {
            currentCriterions.forEach(c => {
                const score = scores[p.id]?.[c.name];
                if (score !== undefined) {
                    socket.emit('submitScore', {
                        juryName,
                        candidate: p.name,
                        team: p.team,
                        section: currentSectionName,
                        criterion: c.name,
                        score: score
                    });
                }
            });
        });

        // Move to next section
        if (currentSectionIndex < sectionNames.length - 1) {
            setCurrentSectionIndex(currentSectionIndex + 1);
        } else {
            alert("Évaluation terminée !");
            // Optionally navigate to dashboard
        }
    };

    return (
        <div className="simultaneous-evaluation-container">
            <h1>Évaluation Simultanée - {currentSectionName}</h1>
            <p>Évaluateur: {juryName}</p>

            <table className="evaluation-table">
                <thead>
                    <tr>
                        <th>Participant</th>
                        {currentCriterions.map(c => <th key={c.name}>{c.name}</th>)}
                    </tr>
                </thead>
                <tbody>
                    {participants.map(p => (
                        <tr key={p.id}>
                            <td>{p.name}</td>
                            {currentCriterions.map(c => (
                                <td key={c.name}>
                                    <input 
                                        type="number" 
                                        min={c.min} 
                                        max={c.max}
                                        value={scores[p.id]?.[c.name] || ''}
                                        onChange={(e) => handleScoreChange(p.id, c.name, parseInt(e.target.value))}
                                    />
                                </td>
                            ))}
                        </tr>
                    ))}
                </tbody>
            </table>

            <button onClick={handleSubmitSection} className="next-btn">
                {currentSectionIndex < sectionNames.length - 1 ? 'Valider et passer à la section suivante' : 'Terminer l\'évaluation'}
            </button>
        </div>
    );
};

export default SimultaneousEvaluation;
